import React, { useEffect, useState } from 'react';
import { MapContainer, TileLayer, Polyline, Popup } from 'react-leaflet';

function App() {
  const [rotas, setRotas] = useState([]);

  useEffect(() => {
    // tenta buscar do backend, se falhar usa uma rota fake
    fetch('http://localhost:3001/api/rotas')
      .then(r => r.json())
      .then(data => setRotas(data))
      .catch(() => setRotas([
        { id: 1, nome: 'Rua Exemplo - Livre', coords: [[-12.97, -38.5], [-12.98, -38.51]], status: 'livre', co2: 0.5 },
        { id: 2, nome: 'Av. Principal - Congestionada', coords: [[-12.96, -38.49], [-12.97, -38.5]], status: 'congestionado', co2: 1.8 }
      ]));
  }, []);

  return (
    <div style={{ padding: '20px', fontFamily: 'Arial' }}>
      <h1>🌿 Cidades Inteligentes</h1>
      <p>Mapa funcionando! Verde = livre, Vermelho = congestionado</p>
      <MapContainer center={[-12.97, -38.51]} zoom={13} style={{ height: '500px', width: '100%', borderRadius: '10px' }}>
        <TileLayer 
          url="https://{s}.tile.openstreetmap.fr/rtiles/voyager/{z}/{x}/{y}{r}.png"
          attribution='&copy; OpenStreetMap &copy; CARTO'
        />
        {rotas.map(rota => (
          <Polyline key={rota.id} positions={rota.coords} color={rota.status === 'congestionado' ? 'red' : 'green'} weight={6}>
            <Popup><b>{rota.nome}</b><br/>CO2: {rota.co2}kg<br/>Status: {rota.status}</Popup>
          </Polyline>
        ))}
      </MapContainer>
    </div>
  );
}
export default App;
